package org.bytefred.ksat.minisat

import org.junit.AssumptionViolatedException
import java.io.File
import kotlin.test.Test
import kotlin.test.fail

/**
 * Incremental live shadow test (JVM only): the scripts in ksat-extra/shadow/minisat-scripts/
 * (generated by ksat-extra/shadow/tools/gen_minisat_scripts.py; format: minisat-full/driver_script.h)
 * run on ONE solver each, many solves with adds, assumptions, releases, budgets and interrupts
 * in between, in the reference driver's `--script` mode and in [MiniSatShadowDriver.runScript].
 * The complete output (OP/RET/VAR/MODEL/FAILED lines and the trace) is compared line by line,
 * live (no trace files). `<name>.core.ops` runs with --simp=0, `<name>.simp.ops` with --simp=1,
 * each without options and with two option sets.
 * - [portMatchesMasterScripts]: default port vs. ksat-extra/shadow/minisat-master (fixed master);
 * - [csbCompatMatchesCsbScripts]: [MiniSat.csbCompat] = true vs. ksat-extra/shadow/minisat-full.
 * SKIPPED (visibly) when ksat-extra, the scripts or a built reference binary are missing.
 */
class MiniSatIncrementalShadowTest {

    private fun skip(reason: String): Nothing {
        System.err.println("$TAG SKIPPED: $reason")
        throw AssumptionViolatedException(reason)
    }

    @Test
    fun portMatchesMasterScripts() = compare("minisat-master", "minisat_master_trace", csb = false)

    @Test
    fun csbCompatMatchesCsbScripts() = compare("minisat-full", "minisat_full_trace", csb = true)

    private fun compare(refDir: String, binName: String, csb: Boolean) {
        val shadow = MiniSatShadowDriver.locateShadowDir() ?: skip("no ksat-extra/shadow found")
        val bin = File(shadow, "$refDir/build/$binName")
        if (!bin.canExecute())
            skip("reference not built: run `bash ${File(shadow, "$refDir/build_and_trace.sh")} --build-only`")
        val scripts = File(shadow, "minisat-scripts").listFiles { f -> f.name.endsWith(".ops") }?.sortedBy { it.name }
        if (scripts.isNullOrEmpty())
            skip("no scripts: run `python3 ${File(shadow, "tools/gen_minisat_scripts.py")}`")
        val failures = ArrayList<String>()
        var n = 0
        var lines = 0L
        for (script in scripts) {
            val simp = when {
                script.name.endsWith(".core.ops") -> 0
                script.name.endsWith(".simp.ops") -> 1
                else -> fail("$TAG script name must end with .core.ops or .simp.ops: $script")
            }
            for (opts in OPTION_SETS) {
                if (simp == 0 && opts.any { it.substringBefore('=').removePrefix("--") in SIMP_OPTIONS }) continue
                n++
                val label = "[$refDir ${script.name} simp=$simp $opts]"
                val cmd = listOf(bin.path, "--simp=$simp") + opts + "--script=${script.path}"
                val r = LiveCompare.run(cmd, label, { it.isNotEmpty() }) { sink ->
                    MiniSatShadowDriver.runScript({ lines++; sink(it) }, simp, opts, script, TAG, csb = csb)
                }
                if (r.diff != null) failures += r.diff
                else if (r.exitCode != 0) failures += "$label reference failed (${r.exitCode}): ${r.stderr}"
            }
        }
        println("$TAG [$refDir] compared $n script runs ($lines lines), ${failures.size} failing")
        if (failures.isNotEmpty()) fail("$TAG ${failures.size} mismatches:\n" + failures.take(10).joinToString("\n"))
    }

    private companion object {
        const val TAG = "[incremental-shadow-minisat]"
        val SIMP_OPTIONS = setOf("asymm", "rcheck", "elim", "grow", "cl-lim", "sub-lim", "simp-gc-frac")
        val OPTION_SETS: List<List<String>> = listOf(
            emptyList(),
            listOf("--rnd-freq=0.1", "--rnd-init=1", "--rnd-seed=12345", "--ccmin-mode=1", "--luby=0", "--gc-frac=0.01"),
            listOf("--asymm=1", "--rcheck=1", "--grow=2", "--phase-saving=1", "--min-learnts=5", "--simp-gc-frac=0.01"),
        )
    }
}
